def transform(grid):
    h,w=len(grid),len(grid[0])
    # Output is the boolean overlap of equal-sized regions separated by
    # a single full-color divider row or column. Divider remains excluded.
    for r in range(h):
        if len(set(grid[r]))==1 and r>0 and h-r-1==r:
            return [[2 if a!=0 and b!=0 else 0 for a,b in zip(x,y)] for x,y in zip(grid[:r],grid[r+1:])]
    for c in range(w):
        if all(grid[i][c]==grid[0][c] for i in range(h)) and c>0 and w-c-1==c:
            return [[2 if row[i]!=0 and row[j]!=0 else 0 for i,j in zip(range(c),range(c+1,w))] for row in grid]
    raise ValueError('no centered divider with equal panels')

if __name__=='__main__':
 import json,sys
 print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}
